// Generated by Cypress Author on 2026-11-24.
// Group the locked-out-user authentication scenario.
describe('Swag Labs authentication', () => {
  // Define the single locked-out-user login scenario.
  it('locked-out user → stays on the login page and shows an error', () => {
    // Open the Swag Labs login page.
    cy.visit('/');

    // Enter the locked-out user's username.
    cy.get('[data-test="username"]').type('locked_out_user');
    // Enter the standard password.
    cy.get('[data-test="password"]').type('secret_sauce');
    // Submit the login form.
    cy.get('[data-test="login-button"]').click();

    // Confirm the browser remains on the login page.
    cy.location('pathname').should('eq', '/');
    // Confirm the error is visible and contains the locked-out message.
    cy.get('[data-test="error"]').should('be.visible').and('contain', 'Epic sadface: Sorry, this user has been locked out.');
  });
});
